requirements.instances:
// Expect labels apply when the target requirement is enforced during evaluation.
 // Positive: the user who posts an ad has no non-ad posts; the other user's non-ad is seen only by a follower.
run PositiveScenario1 {
  some disj u0, u1: User, a, p: Photo, d: Day {
    User = u0 + u1
    Influencer = u1
    Photo = a + p
    Ad = a
    Day = d
    follows = u0 -> u1
    sees = u0 -> a + u1 -> a + u0 -> p
    posts = u0 -> a + u1 -> p
    suggested = none -> none
    date = (a + p) -> d
  }
} for exactly 2 User, exactly 2 Photo, exactly 1 Day expect 1

// Positive: the sole user's only post is an ad, which is visible to that user.
run PositiveScenario2 {
  some u: User, a: Photo, d: Day {
    User = u
    Influencer = none
    Photo = a
    Ad = a
    Day = d
    follows = none -> none
    sees = u -> a
    posts = u -> a
    suggested = none -> none
    date = a -> d
  }
} for exactly 1 User, exactly 1 Photo, exactly 1 Day expect 1

// Positive: there are no ads, and the non-ad is seen only by a user who follows its poster.
run PositiveScenario3 {
  some disj u0, u1: User, p: Photo, d: Day {
    User = u0 + u1
    Influencer = u1
    Photo = p
    Ad = none
    Day = d
    follows = u1 -> u0
    sees = u1 -> p
    posts = u0 -> p
    suggested = none -> none
    date = p -> d
  }
} for exactly 2 User, exactly 1 Photo, exactly 1 Day expect 1

// Negative: one user posts both an ad and a non-ad, violating the target; the non-ad is not seen.
run NegativeScenario1 {
  some u: User, disj a, p: Photo, d: Day {
    User = u
    Influencer = none
    Photo = a + p
    Ad = a
    Day = d
    follows = none -> none
    sees = u -> a
    posts = u -> a + u -> p
    suggested = none -> none
    date = (a + p) -> d
  }
} for exactly 1 User, exactly 2 Photo, exactly 1 Day expect 0

// Negative: u0 posts an ad and a non-ad; u1 follows u0 and may see that non-ad.
run NegativeScenario2 {
  some disj u0, u1: User, disj a, p, q: Photo, d: Day {
    User = u0 + u1
    Influencer = u1
    Photo = a + p + q
    Ad = a
    Day = d
    follows = u1 -> u0
    sees = u0 -> a + u1 -> a + u1 -> p
    posts = u0 -> a + u0 -> p + u1 -> q
    suggested = none -> none
