requirements.instances:
// Expect labels apply when the target requirement is enforced during evaluation.
// PositiveScenario1: distinct entry and exit tracks; no signals or track links.
run PositiveScenario1 {
  some disj t0, t1: Track |
    Track = t0 + t1 and
    Entry = t0 and Exit = t1 and Junction = none and
    Signal = none and Semaphore = none and Speed = none and
    Track <: succs = none->none and
    Track <: signals = none->none
} for 2 but exactly 2 Track, exactly 0 Signal expect 1

// PositiveScenario2: one track serves as both entry and exit and carries a speed signal.
run PositiveScenario2 {
  some t0: Track |
    some s0: Signal |
      Track = t0 and
      Entry = t0 and Exit = t0 and Junction = t0 and
      Signal = s0 and Semaphore = none and Speed = s0 and
      Track <: succs = none->none and
      Track <: signals = t0->s0
} for 1 but exactly 1 Track, exactly 1 Signal expect 1

// PositiveScenario3: entry-to-exit path through a junction, with both signal extensions represented.
run PositiveScenario3 {
  some disj t0, t1, t2: Track |
    some disj s0, s1: Signal |
      Track = t0 + t1 + t2 and
      Entry = t0 and Exit = t2 and Junction = t1 and
      Signal = s0 + s1 and Semaphore = s0 and Speed = s1 and
      Track <: succs = t0->t1 + t1->t2 and
      Track <: signals = t0->s0 + t2->s1
} for 3 but exactly 3 Track, exactly 2 Signal expect 1

// NegativeScenario1: the station has neither an entry nor an exit.
run NegativeScenario1 {
  Track = none and Entry = none and Exit = none and Junction = none and
  Signal = none and Semaphore = none and Speed = none and
  Track <: succs = none->none and
  Track <: signals = none->none
} for 0 but exactly 0 Track, exactly 0 Signal expect 0

// NegativeScenario2: the sole track is an entry, but there is no exit.
run NegativeScenario2 {
  some t0: Track |
    Track = t0 and
    Entry = t0 and Exit = none and Junction = t0 and
    Signal = none and Semaphore = none and Speed = none and
    Track <: succs = none->none and
    Track <: signals = none->none
} for 1 but exactly 1 Track, exactly 0 Signal expect 0

// NegativeScenario3: there is an exit and a path, but no entry.
run NegativeScenario3 {
  some disj t0, t1: Track |
    some s0: Signal |
      Track = t0 + t1 and
      Entry = none and Exit = t1 and Junction = t0 and
      Signal = s0 and Semaphore = s0 and Speed = none and
      Track <: succs = t0->t1 and
      Track <: signals = t0->s0
} for 2 but exactly 2 Track, exactly 1 Signal expect 0

