// Expect labels apply when the target requirement is enforced during evaluation.
// PositiveScenario1: t1 is the sole track without a successor, and it is the sole exit.
run PositiveScenario1 {
  some disj t0, t1: Track |
  some disj s0: Signal |
    Track = t0 + t1 and
    Junction = none and Entry = t0 and Exit = t1 and
    Signal = s0 and Semaphore = none and Speed = none and
    Track <: succs = t0->t1 and
    Track <: signals = t0->s0
} for 2 but exactly 2 Track, exactly 1 Signal expect 1

// PositiveScenario2: the single track is both an entry and an exit, and has no successor.
run PositiveScenario2 {
  some disj t0: Track |
  some disj s0: Signal |
    Track = t0 and
    Junction = none and Entry = t0 and Exit = t0 and
    Signal = s0 and Semaphore = s0 and Speed = none and
    Track <: succs = none->none and
    Track <: signals = t0->s0
} for 1 but exactly 1 Track, exactly 1 Signal expect 1

// PositiveScenario3: t0 and t1 form a cycle; the only sink, t2, is the only exit.
run PositiveScenario3 {
  some disj t0, t1, t2: Track |
  some disj s0, s1: Signal |
    Track = t0 + t1 + t2 and
    Junction = t1 and Entry = t0 and Exit = t2 and
    Signal = s0 + s1 and Semaphore = s0 and Speed = s1 and
    Track <: succs = t0->t1 + t1->t0 and
    Track <: signals = t0->s0 + t2->s1
} for 3 but exactly 3 Track, exactly 2 Signal expect 1

// NegativeScenario1: t0 has no successor but is not an exit.
run NegativeScenario1 {
  some disj t0, t1: Track |
  some disj s0: Signal |
    Track = t0 + t1 and
    Junction = none and Entry = t0 and Exit = t1 and
    Signal = s0 and Semaphore = none and Speed = none and
    Track <: succs = none->none and
    Track <: signals = t1->s0
} for 2 but exactly 2 Track, exactly 1 Signal expect 0

// NegativeScenario2: the exit t0 has a successor.
run NegativeScenario2 {
  some disj t0, t1: Track |
  some disj s0: Signal |
    Track = t0 + t1 and
    Junction = t1 and Entry = t1 and Exit = t0 and
    Signal = s0 and Semaphore = s0 and Speed = none and
    Track <: succs = t0->t1 + t1->t1 and
    Track <: signals = t1->s0
} for 2 but exactly 2 Track, exactly 1 Signal expect 0

